export const getSyncRoomId = ({ pageUid }: { pageUid: string }): string => {
  const graphName = window.roamAlphaAPI.graph.name;
  const payload = JSON.stringify({ graphName, pageUid });
  const bytes = new TextEncoder().encode(payload);
  let binary = "";
