  async run({ page }) {
    return page.evaluate(() => {
      const api = window.roamAlphaAPI;
      const q = (s, ...a) => api.data.fast.q(s, ...a);
      const pull = (uid) =>
        api.pull(
          "[:block/uid :block/string :block/order :block/heading {:block/children ...}]",
          [":block/uid", uid],
        );
      const simplify = (n) =>
        n
          ? {
              uid: n[":block/uid"],
              text: (n[":block/string"] || "").slice(0, 160),
              heading: n[":block/heading"],
              children: (n[":block/children"] || [])
                .sort((a, b) => (a[":block/order"] ?? 0) - (b[":block/order"] ?? 0))
                .map(simplify),
            }
          : null;
      const nodes = window.roamjs.extension.queryBuilder.getDiscourseNodes();
      const qbNodes = nodes
        .filter((n) => n.canvasSettings?.["key-image"])
        .map((n) => ({
          type: n.type,
          text: n.text,
          format: n.format,
          keyImage: n.canvasSettings["key-image"],
          option: n.canvasSettings["key-image-option"],
          alias: n.canvasSettings["query-builder-alias"],
          template: (n.template || []).map((t) => ({ text: t.text, heading: t.heading, children: (t.children || []).map((c) => c.text) })),
        }));
      const resolveAlias = (alias) => {
        if (!alias) return null;
        const byInclude = q(
          `[:find ?uid :where [?b :block/uid ?uid] [?b :block/string ?s] [[clojure.string/includes? ?s "{{query block:${alias}}}"]]]`,
        )[0]?.[0];
        const byTitle = q(`[:find ?uid :where [?b :node/title "${alias}"] [?b :block/uid ?uid]]`)[0]?.[0];
        const uid = byInclude || byTitle || null;
        return { uid, viaInclude: !!byInclude, viaTitle: !!byTitle, tree: uid ? simplify(pull(uid)) : null };
      };
      const queries = Object.fromEntries(qbNodes.map((n) => [n.type, resolveAlias(n.alias)]));
      // Recently edited pages that contain an image block, to see where images landed
      const recent = q(
        `[:find ?title ?uid ?t :where [?p :node/title ?title] [?p :block/uid ?uid] [?p :edit/time ?t] [?b :block/page ?p] [?b :block/string ?s] [[clojure.string/includes? ?s "![](https://"]]]`,
      )
        .sort((a, b) => b[2] - a[2])
        .slice(0, 4)
        .map(([title, uid]) => ({ title, tree: simplify(pull(uid)) }));
      return { qbNodes, queries, recentImagePages: recent };
    });
  },
};
