      const dl = `[:find ?uid :in $ ?title :where [?p :node/title ?title] [?h1 :block/page ?p] [?h1 :block/heading 1] [?node :block/parents ?h1] [?node :block/uid ?uid]]`;
      const t0 = performance.now();
      const local = await api.data.async.fast.q(dl, title);
      const backend0 = await api.data.backend.q(dl, title);
      const t1 = performance.now();
      await new Promise((r) => setTimeout(r, 3000));
      const backend3s = await api.data.backend.q(dl, title);
      return { title, pageUid, childUid, local: local.flat(), backendImmediate: backend0.flat(), backendAfter3s: backend3s.flat(), backendImmediateMs: Math.round(t1 - t0) };
