export default {
  async run({ page }) {
    return page.evaluate(async () => {
      const api = window.roamAlphaAPI;
      const gen = () => api.util.generateUID();
      // Mirrors the Issue query: node in page with title NODETEXT, node has parent h1, h1 has heading 1
      const dl = `[:find ?uid :in $ ?title :where [?p :node/title ?title] [?node :block/page ?p] [?node :block/parents ?h1] [?h1 :block/heading 1] [?node :block/uid ?uid]]`;
      const scenario = async (label, withPlaceholder) => {
        const title = `[[ISS]] - dg-eng1356-repro-${label}-${Date.now()}`;
        const pageUid = gen();
        const h1Uid = gen();
        await api.data.page.create({ page: { title, uid: pageUid } });
        await api.data.block.create({ location: { "parent-uid": pageUid, order: 0 }, block: { uid: h1Uid, string: "Key Image", heading: 1 } });
        await api.data.block.create({ location: { "parent-uid": pageUid, order: 1 }, block: { string: "__properties__ #.properties" } });
        if (withPlaceholder) {
          await api.data.block.create({ location: { "parent-uid": h1Uid, order: 0 }, block: { string: "" } });
        }
        const backendImmediate = (await api.data.backend.q(dl, title)).flat();
        const localImmediate = (await api.data.async.fast.q(dl, title)).flat();
        await new Promise((r) => setTimeout(r, 3000));
        const backendAfter3s = (await api.data.backend.q(dl, title)).flat();
        return { label, pageUid, backendImmediate, localImmediate, backendAfter3s };
      };
      return [await scenario("template-as-is", false), await scenario("with-child-under-h1", true)];
    });
  },
  async cleanup({ page, state }) {
    if (!Array.isArray(state)) return "nothing to clean";
    return page.evaluate(async (uids) => {
      for (const uid of uids) await window.roamAlphaAPI.data.page.delete({ page: { uid } });
      return `deleted ${uids.length} scratch pages`;
    }, state.map((s) => s.pageUid));
  },
};
EOF
